    ("log_diag_head", "Diagnostic log", "Nhật ký chẩn đoán", "Journal de diagnostic", "Registro de diagnóstico", "Журнал диагностики", "سجل التشخيص", "诊断日志"),
    ("ui_back_to_menu", "‹ Back to %1$s", "‹ Quay lại %1$s", "‹ Retour à %1$s", "‹ Volver a %1$s", "‹ Назад: %1$s", "‹ العودة إلى %1$s", "‹ 返回%1$s"),
    ('menu_group_reading', 'Reading', 'Đọc', 'Lecture', 'Lectura', 'Чтение', 'القراءة', '朗读'),
